<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {api,clp,date,errorText,currentPeriod} from '../api';import {useAuth} from '../stores/auth';import StatusBadge from '../components/StatusBadge.vue';import PageHeading from '../components/PageHeading.vue';import {ArrowRight,ArrowUpRight,Building2,Clock3,ClipboardCheck} from 'lucide-vue-next';
const auth=useAuth(),works=ref<any[]>([]),charges=ref<any[]>([]),tasks=ref<any[]>([]),docs=ref<any[]>([]),error=ref(''),loading=ref(true),filter=ref('all'),period=ref(currentPeriod());const filtered=computed(()=>works.value.filter(w=>filter.value==='all'||w.status===filter.value));const waiting=computed(()=>works.value.filter(w=>['waiting','not_started'].includes(w.status)).length);const total=computed(()=>charges.value.reduce((n,c)=>n+c.amount,0)),paid=computed(()=>charges.value.reduce((n,c)=>n+c.paid,0));const pendingDocs=computed(()=>docs.value.filter(d=>['pending','correction'].includes(d.status)));
async function load(){loading.value=true;error.value='';try{const [w,c,d]=await Promise.all([api.get('/works',{params:{period:period.value}}),api.get('/charges',{params:{period:period.value}}),api.get('/documents')]);works.value=w.data;charges.value=c.data;docs.value=d.data.filter((x:any)=>x.work?.period===period.value);if(auth.staff)tasks.value=(await api.get('/tasks')).data.filter((t:any)=>t.status!=='completed').slice(0,4);}catch(e){error.value=errorText(e);}finally{loading.value=false;}}onMounted(load);
</script>
<template><PageHeading :title="auth.staff?'Tu estudio, bajo control.':`Hola, ${auth.user.name.split(' ')[0]}.`" :subtitle="auth.staff?'Cada pendiente claro. Cada empresa en su lugar.':'Aquí encontrarás tus pendientes y el avance del trabajo.'"><label class="inline-label">Período<input type="month" v-model="period" @change="load"></label></PageHeading><div v-if="error" class="error" role="alert">{{error}} <button @click="load">Reintentar</button></div><p v-if="loading" class="empty" role="status">Cargando tu espacio…</p><template v-else><section v-if="!auth.staff&&pendingDocs.length" class="client-banner"><div><span class="eyebrow">PARA SEGUIR AVANZANDO</span><h2>{{pendingDocs.length}} antecedentes necesitan tu atención.</h2><p>Adjunta lo solicitado. Tu contador revisará cada archivo.</p></div><RouterLink to="/documents" class="button lime">Ver mis pendientes <ArrowRight :size="16"/></RouterLink></section><div class="stats-grid"><RouterLink to="/companies" class="stat"><div class="stat-label">Empresas con trabajo <Building2 :size="17"/></div><strong>{{new Set(works.map(w=>w.company_id)).size}}</strong><small>En el período seleccionado</small></RouterLink><RouterLink to="/documents" class="stat"><div class="stat-label">Esperando antecedentes <Clock3 :size="17"/></div><strong>{{waiting}}</strong><small>Trabajos pendientes de información</small></RouterLink><RouterLink to="/works?status=review" class="stat"><div class="stat-label">En revisión <ClipboardCheck :size="17"/></div><strong>{{works.filter(w=>w.status==='review').length}}</strong><small>Con preparación terminada</small></RouterLink></div><section class="panel"><div class="panel-heading"><div><span class="eyebrow">OPERACIÓN MENSUAL</span><h2>{{auth.staff?'Trabajo del mes':'El avance de tus trabajos'}}</h2></div><RouterLink to="/works" class="text-link">Ver trabajos <ArrowUpRight :size="15"/></RouterLink></div><div class="filter-tabs"><button v-for="f in [{id:'all',label:'Todos'},{id:'waiting',label:'Esperando antecedentes'},{id:'review',label:'En revisión'},{id:'delivered',label:'Entregados'}]" :key="f.id" @click="filter=f.id" :aria-pressed="filter===f.id">{{f.label}}</button></div><div class="table-wrap"><table><thead><tr><th>Empresa / Servicio</th><th>Estado</th><th>Fecha interna</th><th></th></tr></thead><tbody><tr v-for="w in filtered" :key="w.id"><td><RouterLink :to="`/companies/${w.company_id}`" class="entity-name">{{w.company.name}}</RouterLink><small>{{w.title}} · {{w.period}}</small></td><td><StatusBadge :status="w.status"/></td><td>{{date(w.due_on)}}</td><td><RouterLink :to="`/works?company_id=${w.company_id}`" class="row-action" aria-label="Ver trabajo"><ArrowRight :size="17"/></RouterLink></td></tr></tbody></table><div v-if="!filtered.length" class="empty">No hay trabajos en esta vista.</div></div></section><div class="two-column"><section class="panel" v-if="auth.staff"><div class="panel-heading"><h2>Próximas tareas</h2><RouterLink to="/tasks" class="text-link">Ver agenda</RouterLink></div><div v-for="t in tasks" :key="t.id" class="list-row"><div><strong>{{t.title}}</strong><small>{{t.company?.name}} · {{date(t.due_on)}}</small></div><StatusBadge :status="t.status"/></div><div v-if="!tasks.length" class="empty">Tu agenda está despejada.</div><div class="panel-note">Fechas de trabajo del estudio. No son vencimientos tributarios oficiales.</div></section><section v-else class="panel"><div class="panel-heading"><h2>Tus próximos pasos</h2></div><RouterLink to="/documents" class="list-row">Completar antecedentes <ArrowRight :size="16"/></RouterLink><RouterLink to="/reports" class="list-row">Consultar informes publicados <ArrowRight :size="16"/></RouterLink><RouterLink to="/conversations" class="list-row">Conversar con tu contador <ArrowRight :size="16"/></RouterLink></section><section class="panel"><div class="panel-heading"><h2>Honorarios del período</h2></div><div class="billing-summary"><strong>{{clp(paid)}}</strong><p>{{auth.staff?'Registrados':'Pagados'}} de {{clp(total)}}</p><progress :max="total||1" :value="paid" aria-label="Proporción de honorarios pagados"></progress><RouterLink to="/billing" class="text-link">Consultar honorarios <ArrowRight :size="15"/></RouterLink></div></section></div></template></template>
